-- Enhanced Weather Stations Table with Coordinates and Provider
CREATE TABLE IF NOT EXISTS weather_stations (
    id INT AUTO_INCREMENT PRIMARY KEY,
    name VARCHAR(255) NOT NULL,
    station_code VARCHAR(50),
    region VARCHAR(100),
    type VARCHAR(10),
    station_id VARCHAR(50),
    group_id VARCHAR(50),
    provider VARCHAR(100),
    observations_url VARCHAR(500),
    forecast_url VARCHAR(500),
    forecast_chart_url VARCHAR(500),
    info_url VARCHAR(500),
    data_url VARCHAR(500),
    latitude DECIMAL(10, 7),
    longitude DECIMAL(10, 7),
    elevation DECIMAL(8, 2),
    description TEXT,
    established VARCHAR(4),
    municipality VARCHAR(100),
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    UNIQUE KEY unique_station_code (station_code),
    UNIQUE KEY unique_station_id (station_id),
    INDEX idx_region (region),
    INDEX idx_type (type),
    INDEX idx_provider (provider),
    INDEX idx_coordinates (latitude, longitude)
);

